program.source:
Algoritmo Week
  Dimension temperatures[7] Como Entero;
  Definir sum Como Entero <- 0;
  Para i <- 0 Hasta 7 Hacer
    Leer temperatures[i];
    sum <- sum + temperatures[i];
  FinPara
  Escribir sum;
FinAlgoritmo

